<section class="card"><div class="card-header between"><div><h2>La historia de cada acuerdo</h2><p>Movimientos con usuario, área y fecha de Lima.</p></div><a class="btn btn-secondary" href="index.php?<?= e(http_build_query(['export' => 'timeline', 'q' => $q, 'role' => $_GET['role'] ?? ''])) ?>">Exportar CSV ↓</a></div><form method="get" class="toolbar"><input type="hidden" name="page" value="timeline"><label class="sr-only" for="event-q">Buscar movimientos</label><input id="event-q" name="q" value="<?= e($q) ?>" placeholder="Cliente, persona o movimiento"><label class="sr-only" for="event-role">Área</label><select id="event-role" name="role"><option value="">Todas las áreas</option><?php foreach ($roles as $key => $label): ?><option value="<?= e($key) ?>" <?= ($_GET['role'] ?? '') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach ?></select><button class="btn btn-primary">Filtrar</button></form><div class="section-body"><?php $found = false; foreach ($events as $event): if (($q !== '' && mb_stripos(implode(' ', $event), $q) === false) || (($_GET['role'] ?? '') !== '' && $event['role'] !== $_GET['role'])) continue; $found = true; ?><article class="timeline-event"><div class="between"><strong><?= e($event['action']) ?></strong><small><?= e(date('d/m/Y H:i', strtotime($event['created_at']))) ?></small></div><p><?= e($event['detail']) ?></p><small><?= e($event['user_name']) ?> · <?= e($roles[$event['role']]) ?> · <a href="index.php?page=detail&amp;id=<?= e($event['contract_id']) ?>"><?= e($event['code'] . ' · ' . $event['client']) ?></a></small></article><?php endforeach ?><?php if (!$found): ?><p class="empty-state">No encontramos movimientos.</p><?php endif ?></div></section>

